#!/usr/bin/env python3
"""Offline, diskless password manager.

Nothing is ever written to disk. The vault lives in memory and is exported as an
encrypted text blob (scrypt-derived key + Fernet/AES-128-CBC+HMAC) that YOU keep
(clipboard, notes app, shell redirect). Paste it back next session, or set the
PM_VAULT environment variable (the terminal truncates pasted lines > 4096 chars).
"""
import base64
import binascii
import getpass
import hashlib
import json
import os
import secrets
import string
import sys

from cryptography.fernet import Fernet, InvalidToken

SCRYPT = dict(n=2**15, r=8, p=1, maxmem=64 * 1024 * 1024)
SALT_LEN = 16
HELP = ("commands: add <name> <user> [length] | get <name> | list | del <name> "
        "| gen [length] | save | help | quit")


class VaultError(Exception):
    pass


def _key(master, salt):
    return base64.urlsafe_b64encode(hashlib.scrypt(master.encode(), salt=salt, **SCRYPT))


def seal(vault, master):
    """Encrypt a vault dict into a printable blob (fresh salt every time)."""
    salt = os.urandom(SALT_LEN)
    token = Fernet(_key(master, salt)).encrypt(json.dumps(vault).encode())
    return base64.urlsafe_b64encode(salt + token).decode()


def unseal(blob, master):
    """Decrypt a blob; raises VaultError on bad input or wrong password."""
    try:
        raw = base64.urlsafe_b64decode(blob.strip().encode())
        token = Fernet(_key(master, raw[:SALT_LEN])).decrypt(raw[SALT_LEN:])
        return json.loads(token)
    except (binascii.Error, ValueError, InvalidToken):
        raise VaultError("wrong master password or corrupted vault") from None


def generate(length=20):
    if length < 8:
        raise ValueError("length must be at least 8")
    pool = string.ascii_letters + string.digits + "!@#$%^&*-_=+"
    return "".join(secrets.choice(pool) for _ in range(length))


def _command(vault, cmd, args):
    """Run one command; returns (message, changed)."""
    if cmd == "add" and len(args) in (2, 3):
        name, user = args[:2]
        pw = generate(int(args[2])) if len(args) == 3 else generate()
        vault[name] = {"user": user, "password": pw}
        return f"stored {name} ({user}): {pw}", True
    if cmd == "get" and len(args) == 1:
        e = vault.get(args[0])
        return (f"{e['user']}: {e['password']}" if e else f"no entry {args[0]!r}"), False
    if cmd == "list" and not args:
        return "\n".join(sorted(vault)) or "(empty)", False
    if cmd == "del" and len(args) == 1:
        found = vault.pop(args[0], None) is not None
        return ("deleted" if found else f"no entry {args[0]!r}"), found
    if cmd == "gen" and len(args) <= 1:
        return generate(int(args[0]) if args else 20), False
    return HELP, False


def main(argv=None, input_fn=input, secret_fn=getpass.getpass, out=sys.stdout, env=os.environ):
    def say(msg):
        print(msg, file=out)

    blob = env.get("PM_VAULT") or input_fn("Vault blob (empty for new vault): ").strip()
    master = secret_fn("Master password: ")
    if not master:
        say("error: master password required")
        return 1
    try:
        if blob:
            vault = unseal(blob, master)
        elif secret_fn("Confirm master password: ") == master:
            vault = {}
        else:
            say("error: passwords do not match")
            return 1
    except VaultError as e:
        say(f"error: {e}")
        return 1

    dirty = False
    say(HELP)
    while True:
        try:
            parts = input_fn("> ").split()
        except EOFError:
            parts = ["quit"]
        if not parts:
            continue
        cmd, args = parts[0].lower(), parts[1:]
        if cmd in ("quit", "exit", "save"):
            if dirty or cmd == "save":
                say("Save this encrypted vault (it is NOT stored anywhere else):")
                say(seal(vault, master))
                dirty = False
            if cmd != "save":
                return 0
            continue
        try:
            msg, changed = _command(vault, cmd, args)
        except ValueError as e:
            msg, changed = f"error: {e}", False
        dirty = dirty or changed
        say(msg)


if __name__ == "__main__":
    sys.exit(main())

