import io

import pytest

import pm


@pytest.fixture(autouse=True)
def fast_kdf(monkeypatch):
    monkeypatch.setattr(pm, "SCRYPT", dict(n=2**4, r=8, p=1, maxmem=64 * 1024 * 1024))


def run(lines, secrets_=("pw", "pw"), env=None):
    lines, secrets_ = iter(lines), iter(secrets_)

    def inp(_):
        try:
            return next(lines)
        except StopIteration:
            raise EOFError

    out = io.StringIO()
    code = pm.main(input_fn=inp, secret_fn=lambda _: next(secrets_), out=out, env=env or {})
    return code, out.getvalue()


def blob_of(output):
    return output.strip().splitlines()[-1]


def test_roundtrip_and_fresh_salt():
    a, b = pm.seal({"x": 1}, "pw"), pm.seal({"x": 1}, "pw")
    assert a != b and pm.unseal(a, "pw") == {"x": 1}


@pytest.mark.parametrize("blob,pw", [("!!!", "pw"), ("", "pw"), (pm.seal({}, "pw"), "bad")])
def test_unseal_errors(blob, pw):
    with pytest.raises(pm.VaultError):
        pm.unseal(blob, pw)


def test_generate():
    assert len(pm.generate(30)) == 30 and pm.generate() != pm.generate()
    with pytest.raises(ValueError):
        pm.generate(4)


def test_session_persists_between_runs():
    code, out = run(["", "add site me 12", "get site", "list", "quit"])
    assert code == 0
    pw = out.split("stored site (me): ")[1].split()[0]
    assert len(pw) == 12 and f"me: {pw}" in out
    code, out2 = run([blob_of(out), "get site", "del site", "del site", "list"], ("pw",))
    assert f"me: {pw}" in out2 and "deleted" in out2 and "no entry 'site'" in out2
    assert "(empty)" in out2


def test_env_vault_and_save_command():
    blob = pm.seal({"a": {"user": "u", "password": "p"}}, "pw")
    code, out = run(["get a", "save", "add b u", "quit"], ("pw",), env={"PM_VAULT": blob})
    assert code == 0 and "u: p" in out and out.count("Save this") == 2
    assert pm.unseal(blob_of(out), "pw").keys() == {"a", "b"}


def test_clean_quit_prints_no_blob():
    _, out = run(["get nothing", "quit"])
    assert "Save this" not in out


def test_misc_commands_and_input():
    _, out = run(["", "gen 10", "gen 2", "add x", "add x y zz", "bogus", "ADD q w", "quit"])
    assert "error: length must be at least 8" in out
    assert "error: invalid literal" in out and out.count("commands:") == 3  # banner+2 bad
    assert "stored q (w)" in out


def test_eof_quits():
    assert run(["add a b"])[0] == 0


def test_startup_failures():
    assert run([""], ("",))[0] == 1
    code, out = run([""], ("a", "b"))
    assert code == 1 and "do not match" in out
    code, out = run([pm.seal({}, "pw")], ("wrong",))
    assert code == 1 and "wrong master password" in out

